def selected_fields(name):
 allf=entities[name]
 if name in priority:return [f for k in priority[name] for f in allf if f[1]==k]
 return allf[:7]
for i,f in enumerate(manifest['features']):
 names=groups[i];src='classDiagram\ndirection TB\n'
 for n in names:
  src+='class '+n+' {\n'
  for ty,field in selected_fields(n):src+=' +'+ty+' '+field+'\n'
  for op in methods.get(n,[]):src+=' +'+op+'\n'
  src+='}\n'
 for a,rel,b,label in relations:
  if a in names and b in names:
   left,right=rel.split('..')
   card={'||':'1','o|':'0..1','|{':'1..*','o{':'0..*'}
   if left in card and right in card:src+=f'{a} "{card[left]}" --> "{card[right]}" {b} : {label}\n'
 (D/(f['classdiag']+'.mmd')).write_text(src)
 # Sequence collaboration matches the sample: Actor, UI, Controller, Service, Repository, Database.
 for sn,title in f['seqs']:
  src=(OLD/'diagrams'/(sn+'.mmd')).read_text()
  lines=src.splitlines();actors=re.findall(r'^\s*actor (\w+) as (.+)$',src,re.M)
  # Choose the primary use-case coordinator as the controller entry point.
  primary={'05':'S','06':'S' if sn.endswith('sync') else 'S','07':'S','08':'S','09':'C' if sn.endswith('assess') else 'E','10':'P','11':'D' if sn.endswith('documents') else 'S','12':'T' if sn.endswith('trace') else 'H','13':'H'}[f['id']]
  # For internal compliance assessment, no new human entry point is introduced.
  internal=sn.endswith('sequence_assess')
  declarations=[];body=[]
  declared={}
  for l in lines[1:]:
   l=l.strip()
   if l.startswith(('participant ','actor ')):
    m=re.match(r'(?:participant|actor) (\w+) as (.+)',l)
    if m: declared[m[1]]=m[2]
   else:body.append(l)
  ui=next((k for k,v in declared.items() if k in ['UI'] or 'Field Client' in v or v=='Workspace' or v=='FieldCaptureService'),None)
  # C is a collaborator in most diagrams; avoid alias collision.
  uiid=ui or 'View';controller='Ctrl';repo='Repo'
  service_name=declared.get(primary,'ApplicationService')
  controller_name=service_name.replace('Service','Controller')
  # one repository/UoW facade per use-case transaction, with specialized domain collaborators still visible
  repo_name=service_name.replace('Service','Repository')
  if service_name in ['FieldCaptureService']:repo_name='ProcurementRepository'
  new=['sequenceDiagram',' autonumber']
  for k,v in declared.items():
   if k in [ui,'DB']:continue
   if any(k==a for a,b in actors):new.append(f' actor {k} as {v}')
  if not internal:
   new.append(f' participant {uiid} as :UI (Web / Field)')
   new.append(f' participant {controller} as :{controller_name}')
  for k,v in declared.items():
   if k in [ui,'DB'] or any(k==a for a,b in actors):continue
   if v in ['Immutable Content Port','ImmutableContentPort']:v=':ImmutableContentStore'
   elif not v.startswith(':'):v=':'+v
   new.append(f' participant {k} as {v}')
  new.append(f' participant {repo} as :{repo_name}')
  new.append(' participant DB as :Database')
  for l in body:
   if not l:continue
   m=re.match(r'(\w+)(--?>>|->>)(\w+):\s*(.*)',l)
   if not m:
    if l.startswith('Note ') and 'DB' in l:l=l.replace('DB','Repo')
    new.append(' '+l);continue
   a,arrow,b,msg=m.groups();human={x for x,y in actors}
   if a in human and b==primary:
    new += [f' {a}->>{uiid}: {msg}',f' {uiid}->>+{controller}: Submit request',f' {controller}->>+{primary}: {msg}']
   elif ui and a==ui and b==primary:
    new += [f' {a}->>+{controller}: {msg}',f' {controller}->>+{primary}: {msg}']
   elif a==primary and b in human:
    new += [f' {a}-->>{controller}: {msg}',f' {controller}-->>{uiid}: Operation result and findings',f' {uiid}-->>{b}: Display outcome']
   elif ui and a==primary and b==ui:
    new += [f' {a}-->>{controller}: {msg}',f' {controller}-->>{ui}: Operation result and findings']
   elif b=='DB':
    new += [f' {a}->>+{repo}: {msg}',f' {repo}->>+DB: {msg}',f' DB-->>-{repo}: Transaction result',f' {repo}-->>-{a}: Result / transaction status']
   else:new.append(' '+l)
  # Branch-specific return messages do not change activation depth. Use explicit whole-service activation.
  new=[l.replace('->>+Ctrl','->>Ctrl').replace('->>+'+primary+':','->>'+primary+':') for l in new]
  # Wrap notes and shorten display names; the full method contracts remain in specifications.
  for j,l in enumerate(new):
   if l.strip().startswith('Note ') and ': ' in l:
    pre,msg=l.split(': ',1);new[j]=pre+': '+'<br/>'.join(textwrap.wrap(msg.replace('<br/>',' '),60))
  (D/(sn+'.mmd')).write_text('\n'.join(new)+'\n')
